#!/bin/bash
# Render every MVP shot in order (flock serialises Blender). Started under systemd-run --user; log: mvp/logs/render.log
set -u; cd /home/apollo/blender-spike; echo "RENDER_START $(date -u +%FT%TZ)"
flock /home/apollo/blender-spike/out/.render.lock /home/apollo/blender-spike/blender/blender -b --python-exit-code 1 -P /home/apollo/blender-spike/mvp/runner.py -- /home/apollo/blender-spike/mvp/shots/shot_01.py anim /home/apollo/blender-spike/mvp/renders/shot_01 121 16 1080 1920 2>&1 | grep -E "MVP_RESULT|Error|Traceback|SIGHTLINE|Saved" | tail -3
flock /home/apollo/blender-spike/out/.render.lock /home/apollo/blender-spike/blender/blender -b --python-exit-code 1 -P /home/apollo/blender-spike/mvp/runner.py -- /home/apollo/blender-spike/mvp/shots/shot_02.py anim /home/apollo/blender-spike/mvp/renders/shot_02 102 16 1080 1920 2>&1 | grep -E "MVP_RESULT|Error|Traceback|SIGHTLINE|Saved" | tail -3
flock /home/apollo/blender-spike/out/.render.lock /home/apollo/blender-spike/blender/blender -b --python-exit-code 1 -P /home/apollo/blender-spike/mvp/runner.py -- /home/apollo/blender-spike/mvp/shots/shot_03.py anim /home/apollo/blender-spike/mvp/renders/shot_03 125 16 1080 1920 2>&1 | grep -E "MVP_RESULT|Error|Traceback|SIGHTLINE|Saved" | tail -3
flock /home/apollo/blender-spike/out/.render.lock /home/apollo/blender-spike/blender/blender -b --python-exit-code 1 -P /home/apollo/blender-spike/mvp/runner.py -- /home/apollo/blender-spike/mvp/shots/shot_04.py anim /home/apollo/blender-spike/mvp/renders/shot_04 171 16 1080 1920 2>&1 | grep -E "MVP_RESULT|Error|Traceback|SIGHTLINE|Saved" | tail -3
flock /home/apollo/blender-spike/out/.render.lock /home/apollo/blender-spike/blender/blender -b --python-exit-code 1 -P /home/apollo/blender-spike/mvp/runner.py -- /home/apollo/blender-spike/mvp/shots/shot_05.py anim /home/apollo/blender-spike/mvp/renders/shot_05 157 16 1080 1920 2>&1 | grep -E "MVP_RESULT|Error|Traceback|SIGHTLINE|Saved" | tail -3
echo "RENDER_DONE $(date -u +%FT%TZ)"
